#!/usr/bin/env python3
"""Rewrite all short chapters with proper ~3000 char content"""
import os

CHAPTERS_DIR = "/root/.openclaw/workspace/novel-projects/novel-05/chapters"

# Check which files need rewriting
needs_rewrite = []
for f in sorted(os.listdir(CHAPTERS_DIR)):
    if not f.endswith('.md'):
        continue
    path = os.path.join(CHAPTERS_DIR, f)
    size = os.path.getsize(path)
    if size < 2000:
        needs_rewrite.append(f)

print(f"Chapters needing rewrite: {len(needs_rewrite)}")

# Chapter plot data with enough detail for ~3000 char expansion
plots = {
    "022": ("二十二", "偶遇徐妙云", """永乐三年春天，秦淮河畔的春江花月诗会上灯火辉煌，文人雅士云集。林昊被周文昌拉来参加这场盛会，原本兴趣不大，却在画舫上看到了一位气质如兰的女子——穿着素色长裙、头簪玉钗的徐妙云。她是中山王徐达之女，才貌双全，名满南京。当徐妙云吟诵出一首改编自《春江花月夜》的诗作时，林昊被深深震撼了——她不仅在背诵经典，更是在再创作。诗会结束后，两人在甲板上偶遇，从诗词聊到经义，从朝政到民生，话题越聊越深。林昊发现，徐妙云的才学远超普通闺秀，她对朝政有着敏锐的洞察力，很多看法与林昊不谋而合。更令林昊惊讶的是，徐妙云主动告诉他："我来这场诗会，是为了见你。"一个名门闺秀，为什么要主动接近一个朝廷新贵？林昊心中充满了疑惑。回到客栈后，他辗转难眠，脑海中一直浮现着徐妙云的身影。他知道，这个女子绝对不简单——她身上藏着太多秘密。而这些秘密，可能会改变他的命运。"""),
    "023": ("二十三", "诗会风云", """诗会的第二天，南京城里到处都在谈论昨晚的盛况。林昊的诗作和徐妙云的改编诗成为了最热门的话题。解缙对林昊的诗大加赞赏，称其"清新脱俗，意境深远"。但成名的代价也随之而来——嫉妒、质疑、拉拢接踵而至。更让林昊警惕的是，汉王朱高煦也出现在了诗会上。朱高煦的目光始终落在徐妙云身上，眼中闪烁着占有欲。诗会结束后，朱高煦在茶馆里找到了林昊。"林大人，昨晚你跟徐妙云聊得很开心嘛。"朱高煦的语气中带着威胁。林昊冷静应对，表示自己对徐妙云并无非分之想。但朱高煦并不相信，他直言不讳地告诉林昊："徐妙云是我看上的人，你最好离她远点。"林昊表面答应，心中却已下定决心——他不会让朱高煦得逞。回到太子府后，林昊将情况告诉了杨士奇。杨士奇的表情变得凝重："子明，汉王盯上了徐妙云，这件事很棘手。你要小心。"林昊点了点头。他知道，自己已经卷入了一场更大的漩涡。"""),
    "024": ("二十四", "秦淮夜话", """诗会过后的第三天，林昊收到了徐妙云的信，约他在秦淮河畔的一间茶馆见面。林昊犹豫再三，最终决定赴约。他需要弄清楚徐妙云的真实目的。茶馆环境清幽，徐妙云已经等在二楼的雅间里。今天的她穿着淡蓝色长裙，素雅大方。"子明，我想跟你合作。"徐妙云开门见山。她告诉林昊，自己有一张情报网，覆盖整个南京城，知道朝中每个人的动向。而林昊有太子的信任和皇上的赏识。两人联手，可以做很多事。"你想做什么？"林昊问道。"我想保护那些在靖难中受害的人。"徐妙云的声音变得低沉，"我的亲生父亲，就是在靖难中被杀的。"林昊终于明白了——徐妙云接近他，不是为了权力，而是为了保护那些无辜的人。月光透过窗户洒进来，映照着两人的身影。林昊做出了决定："好，我答应你。"从这天开始，两人建立了秘密的合作关系。在合作的过程中，他们对彼此的了解越来越深，感情也在不知不觉中发生了变化。"""),
    "025": ("二十五", "诗会扬名", """林昊在诗会上的诗作传遍了南京城，他的名字也随之水涨船高。解缙的评价、商辂的赞叹、杨士奇的推荐，让林昊成为了南京城最热门的话题。但成名的代价也随之而来。翰林院里的一些老学究对林昊的成名非常不满，认为他不过是靠太子的关系上位。有人开始调查林昊的出身，发现他的父亲是建文旧臣。这个消息在暗中传播，成为了一些人攻击林昊的把柄。面对这些麻烦，林昊选择了低调应对。他不再参加公开的文人聚会，将更多的时间和精力放在了《永乐大典》的编纂上。解缙对林昊的工作非常满意，决定让他负责"子部"的编纂——这是《永乐大典》中最复杂的一部分。林昊在翰林院中的地位更加重要，但同时也引来了更多的嫉妒。一天，一个年轻的编修官当面挑衅林昊，质疑他的学问。林昊冷静应对，不卑不亢。他知道，在这个朝堂上，真正的较量不在口舌之争，而在实力和智慧。他需要做的，是继续积累实力，等待时机。"""),
    "037": ("三十七", "暗中的敌人", """林昊发现自己被一股不明势力盯上了。起初他以为是锦衣卫的人，但通过陆炳的调查，发现情况更加复杂——盯梢他的人，竟然是建文旧臣的残余势力。他们怀疑林昊是朱棣派来追杀他们的。"子明，你要小心。"陆炳的表情凝重，"这些人虽然势力大不如前，但他们是亡命之徒，什么都做得出来。"林昊陷入了两难——他既要完成朱棣交给他的任务，又不能伤害那些无辜的人。这些建文旧臣的残余势力，大多是在靖难中失去亲人的可怜人。他们对朱棣恨之入骨，但并没有实际的反抗能力。林昊决定采取一种折中的方式——他继续调查建文帝的下落，但对那些无辜的旧臣后人，他选择了睁一只眼闭一只眼。这个决定，让他在朱棣面前有些被动，但也让他保住了自己的良心。几天后，一个神秘人通过徐妙云的关系网，约林昊见面。林昊知道，这次见面可能会揭开更多的秘密。"""),
    "038": ("三十八", "神秘人", """林昊按照约定，来到了城南的一间小庙。庙里只有一个老和尚在打坐，看起来很平静。但林昊知道，平静的表面下，暗流涌动。片刻后，一个蒙面人从后门走了进来。他穿着一身灰色的长袍，脸上蒙着黑布，只露出一双锐利的眼睛。"你就是林昊？"蒙面人的声音低沉。"正是。"林昊平静地回答，"你是谁？""我是谁不重要。"蒙面人说道，"重要的是，我知道你在调查建文帝的下落。"林昊的心中一紧。蒙面人继续说道："建文帝确实还活着。但他的下落，是一个不能说的秘密。我今天来找你，是想请你——放过我们。""放过你们？""是的。"蒙面人的声音中带着一丝恳求，"我们已经失去了太多。我们不想再有人因为我们而死去。"林昊沉默了。他看着蒙面人的眼睛，看到了其中的悲伤和疲惫。这些人，是靖难之役的受害者。他们失去了亲人，失去了家园，现在还在四处躲藏，苟延残喘。"好。"林昊最终说道，"我答应你。但你也要答应我一件事——不要做任何危害大明的事情。"蒙面人点了点头："我答应你。"说完，他转身离去，消失在了夜色中。林昊站在原地，久久不能平静。他知道，自己刚刚做出了一个可能改变历史的决定。"""),
    "039": ("三十九", "两难抉择", """与蒙面人见面后，林昊陷入了深深的思考。他知道，如果如实向朱棣报告建文帝还活着，那些无辜的旧臣后人将被赶尽杀绝。但如果隐瞒，一旦被发现，他自己也将万劫不复。林昊在忠诚与良知之间挣扎了好几天。最终，他做出了一个折中的决定——向朱棣报告部分真相。"皇上，臣经过调查，建文帝极有可能已经在大火中身亡。"林昊在御书房里恭敬地说道，"出逃的传言，大多是民间的臆测，不可采信。"朱棣盯着林昊看了许久，目光深邃而锐利。"你确定？"朱棣问道。"臣不敢妄断，但根据目前的证据，这个可能性最大。"林昊回答。朱棣沉默了许久，最终点了点头："好。朕知道了。你退下吧。"林昊退出御书房，心中忐忑不安。他不知道朱棣是否相信了他的话。但至少，他保住了那些无辜的人。回到太子府后，杨士奇找到了他。"子明，皇上问了你什么？"杨士奇问道。"关于建文帝的事情。"林昊简要地回答。杨士奇的表情变得凝重："你怎么回答的？""我说建文帝可能已经死了。"杨士奇看了林昊一眼，似乎明白了什么。他没有追问，只是拍了拍林昊的肩膀："好自为之。"林昊点了点头。他知道，自己的选择是对的。"""),
    "040": ("四十", "解缙的拉拢", """这天，解缙约林昊在翰林院的书房里见面。解缙的表情比往常更加热情，这让林昊有些意外。"子明，我有一个提议。"解缙开门见山，"我想让你加入翰林院的核心团队，参与更多《永乐大典》的编纂工作。"林昊沉吟了片刻。解缙的提议很有诱惑力——加入翰林院的核心团队，意味着更多的资源和更高的地位。但林昊也知道，解缙是一个复杂的人。他虽然才华横溢，但性格孤傲，恃才傲物，得罪了很多人。如果跟他走得太近，可能会被牵连。"多谢学士的好意。"林昊拱手道，"但在下更想在太子府做事，为太子殿下效力。"解缙的表情微微一变，但很快就恢复了笑容："也好。太子殿下确实需要你这样的人才。"他顿了顿，又说道："不过，子明，我要提醒你一件事——只依靠太子是不够的。在这个朝堂上，你需要更多的盟友。"林昊听出了弦外之音。解缙在暗示，他应该在多个势力之间寻找平衡，而不是把所有鸡蛋放在一个篮子里。"多谢学士指点。"林昊说道。从翰林院出来后，林昊思考着解缙的话。他知道解缙说得有道理——在权力的游戏中，过于依赖某一方势力是很危险的。但同时，他也知道，忠诚是一种美德。他选择了太子，就不会轻易改变。"""),
    "041": ("四十一", "翰林院的暗流", """林昊留在翰林院继续参与《永乐大典》的编纂工作，但他很快发现，翰林院内部暗流涌动，并不像表面看起来那么平静。编修官们分成了几个派系——有的依附于解缙，有的投靠了汉王朱高煦，还有的保持中立。各派系之间明争暗斗，互相拆台，让编纂工作受到了不小的影响。林昊选择了低调行事。他认真完成自己的编纂任务，不参与派系之争。但他很快就发现，在这个环境下，保持中立几乎是不可能的。一天，一个依附于汉王的编修官找到林昊，暗示他应该投靠汉王。"林大人，汉王殿下很欣赏你的才华。"那个编修官说道，"如果你愿意为汉王效力，高官厚禄不在话下。"林昊婉言拒绝了。但那个编修官并不死心，三番五次地来拉拢。林昊不得不提高了警惕。与此同时，解缙的处境也越来越危险。他的性格太过孤傲，不仅得罪了汉王的人，还得罪了很多中立的大臣。林昊暗中观察着这一切，心中为解缙感到担忧。他知道，以解缙的性格，迟早会出事。但他无能为力——在这个朝堂上，每个人都要为自己的选择负责。"""),
    "042": ("四十二", "徐妙云的秘密", """一个秋天的傍晚，徐妙云约林昊在中山王府见面。这是她第一次邀请林昊来自己的家。中山王府规模宏大，亭台楼阁，花木扶疏。徐妙云带着林昊穿过几重院落，来到了后花园的一间密室里。"子明，我有一件事想告诉你。"徐妙云的表情比往常更加凝重，"这件事，我从来没有告诉过任何人。"林昊看着她的眼睛，点了点头："你说。""我不是徐达的亲生女儿。"徐妙云的声音低沉，"我的亲生父亲，是建文朝的一位重臣。在靖难中，他被朱棣处死了。"林昊的心中一震。"徐家收养了我，保护我免受牵连。"徐妙云继续说道，"他们对外宣称我是徐达的女儿，这样就没有人会怀疑我的身份。"林昊沉默了。他终于明白了，为什么徐妙云会那么关心建文旧臣的命运——因为她自己就是其中之一。"你为什么要把这件事告诉我？"林昊问道。"因为我信任你。"徐妙云的目光坚定，"在这个世界上，你是我唯一信任的人。"林昊感受到了这份信任的重量。他握住徐妙云的手，郑重地说道："我发誓，我会用生命保护你。"徐妙云的眼中闪过一丝感动。她没有说话，只是紧紧地握住了林昊的手。"""),
    "043": ("四十三", "信任的代价", """徐妙云将身世告诉林昊后，两人之间的关系发生了微妙的变化。她不再只是林昊的合作伙伴，更是他想要用生命去保护的人。但林昊也知道，这个秘密如果泄露，后果将不堪设想。徐妙云的亲生父亲是建文旧臣，这意味着她本身就是"建文余孽"。如果有人查出她的身世，不仅她自己会遭殃，连徐家也会受到牵连。林昊开始更加谨慎地行事。他减少了与徐妙云见面的频率，改为通过秘密渠道传递消息。同时，他也加强了对周围环境的警惕，确保没有人跟踪他。"子明，你最近好像很紧张。"杨士奇注意到了林昊的变化。"没什么，只是最近事情比较多。"林昊敷衍道。杨士奇看了他一眼，没有追问。但林昊知道，杨士奇是一个非常敏锐的人，迟早会发现什么。他必须更加小心。几天后，林昊通过陆炳得知，锦衣卫指挥使纪纲似乎对徐家产生了兴趣。纪纲派人暗中调查徐家的底细，包括徐妙云的身世。这个消息让林昊感到了前所未有的危机。他必须想办法阻止纪纲的调查，否则一切都完了。"""),
    "044": ("四十四", "调查者", """纪纲的调查让林昊感到了前所未有的危机。如果纪纲查出徐妙云的真实身世，后果将不堪设想。林昊决定主动出击，转移纪纲的注意力。他通过陆炳的关系，暗中散布了一些关于纪纲手下贪污受贿的消息。这些消息很快就传到了朱棣的耳朵里。朱棣对纪纲的行为产生了不满，下令彻查。纪纲不得不暂时放下对徐家的调查，集中精力应对朱棣的质问。林昊赢得了宝贵的时间。但他知道，这只是暂时的。纪纲是一个睚眦必报的人，他不会轻易放弃。林昊必须想办法彻底解决这个问题。他找到了太子朱高炽，将情况告诉了他。朱高炽的表情变得凝重："子明，这件事很棘手。纪纲是父皇的人，我们很难直接对付他。""但我们可以利用他自己的罪行来对付他。"林昊说道。朱高炽看了林昊一眼，点了点头："好。你去搜集证据，我来想办法。"从这天开始，林昊开始秘密搜集纪纲的罪证。他知道，这是一场没有硝烟的战争，稍有不慎就会粉身碎骨。"""),
    "045": ("四十五", "第一次危机", """纪纲的调查虽然被暂时打断，但他并没有放弃。他暗中安排了更多的密探，监视林昊和徐妙云的一举一动。一天傍晚，林昊从太子府出来，刚走到街角，就被几个黑衣人拦住了。"林大人，纪大人请你去一趟。"为首的黑衣人说道。林昊的心中一紧，但面上不动声色："纪大人找我有什么事？""去了就知道了。"黑衣人的语气不容置疑。林昊知道自己没有选择，只好跟着他们走了。锦衣卫衙门阴森而肃穆。纪纲坐在案后，手中把玩着一枚玉佩，目光阴鸷地盯着林昊。"林大人，"纪纲的声音冰冷，"我有些问题想问你。""纪大人请讲。"林昊平静地回答。"你与徐妙云是什么关系？"纪纲直截了当地问。"朋友。"林昊回答。"朋友？"纪纲冷笑一声，"你们见面的频率，可不像普通朋友。"林昊的心跳加速，但面上依然镇定："在下与徐姑娘确实交往较多，但仅限于诗词唱和，并无其他。"纪纲盯着林昊看了许久，最终挥了挥手："好，你可以走了。但记住，我会一直盯着你。"林昊退出锦衣卫衙门，后背已经被冷汗湿透了。他知道，纪纲不会善罢甘休。他必须尽快想出对策。"""),
    "046": ("四十六", "绝地反击", """被纪纲审问后，林昊知道自己必须反击。如果继续被动挨打，迟早会被纪纲抓住把柄。林昊找到了陆炳，请他帮忙搜集纪纲的罪证。陆炳虽然也是锦衣卫的人，但他对纪纲的专横跋扈早就不满，答应帮林昊的忙。经过一段时间的秘密调查，陆炳找到了纪纲贪污受贿、滥用职权的大量证据。林昊将这些证据整理成报告，通过太子呈给了朱棣。朱棣看了报告后，大为震怒。他下旨彻查纪纲的罪行，纪纲被朱棣严厉训斥，暂时收敛了对林昊的调查。林昊终于松了一口气。但他知道，这只是暂时的胜利。纪纲是一个睚眦必报的人，他一定会寻找机会报复。"子明，你这次做得很好。"杨士奇赞叹道，"但你要记住，纪纲不是那么容易对付的。你要继续小心。"林昊点了点头。他知道，在这个朝堂上，没有永远的胜利，只有永远的警惕。他必须时刻保持清醒的头脑，才能在这个危险的游戏中生存下去。"""),
    "047": ("四十七", "北征的消息", """纪纲被训斥后，暂时收敛了对林昊的针对。林昊终于赢得了一些喘息的时间。就在这时，一个重要的消息传来——朱棣决定北征蒙古。这次北征的目标是鞑靼部，由朱棣亲自率军出征。太子朱高炽留守南京监国。"子明，我想让你随军出征。"太子找到林昊说道。林昊的心中一动。随军出征，意味着他可以在朱棣面前展现自己的军事才能，这是一个难得的机会。但同时，北征也是一件非常危险的事情。"殿下，臣愿意随军。"林昊恭敬地说道。朱高炽满意地点了点头："好。我会向父皇推荐你。"林昊开始为北征做准备。他研究了北方边境的地图和情报，了解了鞑靼部的兵力部署和作战特点。作为历史学者，他对这段历史非常熟悉。他知道，这次北征将会是一场艰苦的战斗，但最终明军会取得胜利。他需要做的，是在这场战斗中发挥自己的作用，为明军的胜利做出贡献。出征的日期很快确定了——永乐八年春。林昊只有几个月的准备时间。他必须在这段时间里，做好一切准备。"""),
    "048": ("四十八", "出征前夜", """出征的日期越来越近，林昊的心情也越来越复杂。他即将踏上北征之路，这将是他在这个时代的第一次真正的军事行动。出征前夜，林昊约徐妙云在秦淮河畔见面。月光如水，河面上波光粼粼。两人并肩坐在河边的石凳上，沉默了很久。"子明，你要小心。"徐妙云终于开口，声音中带着一丝颤抖。"放心，我会平安归来的。"林昊安慰道。徐妙云从怀中取出一枚玉佩，递给林昊："这是我母亲留给我的，你带着它，保你平安。"林昊接过玉佩，感受到了上面残留的体温。他将玉佩贴身收好，郑重地说道："我一定会回来的。"两人紧紧相拥，月光映照着他们的身影。在这个乱世之中，每一次分别都可能是永别。但他们都相信，他们会再次相见。回到客栈后，林昊整理了自己的行装。林福为他准备了足够的干粮和衣物，还有几本兵书。"少爷，您一定要平安回来。"林福的眼中含着泪水。"放心吧，林福。"林昊拍了拍老仆的肩膀，"等我回来。"第二天清晨，大军开拔。林昊骑着马，跟随着大军，踏上了北征之路。他回头望了一眼南京城，心中默默说道：等我回来。"""),
    "049": ("四十九", "北征之路", """大军浩浩荡荡地向北进发。旌旗蔽日，盔甲鲜明，数十万大军排成长龙，绵延数十里。林昊骑在马上，看着这支庞大的军队，心中感慨万千。这是他第一次亲眼见到明朝的军队。与他在文献中读到的不同，真实的明军更加壮观——士兵们训练有素，步伐整齐，盔甲在阳光下闪闪发光。行军途中，林昊与张辅等将领交流。张辅是英国公张玉之子，骁勇善战，是朱棣最倚重的将领之一。"林大人，你一个文人，怎么也来北征了？"张辅笑着问道。"太子殿下让我来学习学习。"林昊谦虚地回答。张辅哈哈大笑："好，那你就跟着我，看看真正的战争是什么样子。"行军数日后，大军到达了北方边境。这里的风景与南京截然不同——荒凉的草原、凛冽的寒风、一望无际的戈壁。林昊裹紧了棉衣，感受着这个时代的北方风光。前方的探子传来消息——鞑靼部的骑兵已经在前方出没。林昊知道，真正的战斗即将开始。"""),
    "050": ("五十", "初露锋芒", """大军在边境驻扎下来，等待着与鞑靼部的决战。林昊利用这段时间，仔细研究了周围的地形。他发现，大军驻扎的地方东面有一片密林，西面有一条小河，北面是一片开阔的草原。这个地形，非常适合设伏。林昊找到了张辅，提出了一个伏击方案。"张将军，鞑靼的先锋骑兵一定会从北面的草原过来。如果我们能在密林中设下埋伏，等他们进入包围圈后再出击，一定能大获全胜。"张辅听了林昊的方案，眼前一亮："好计策！"他立即安排了一支精兵，埋伏在密林中。果然，第二天清晨，鞑靼的先锋骑兵出现在了北方的草原上。他们耀武扬威地向明军的营地冲来，完全没有察觉到危险。当鞑靼骑兵进入包围圈后，张辅一声令下，伏兵四起。明军从密林中杀出，将鞑靼骑兵团团包围。经过一番激战，鞑靼先锋骑兵被全歼，斩首数百。林昊的军事才能得到了将领们的认可。"林大人，你这一手伏击计，真是妙啊！"张辅赞叹道。林昊谦虚地笑了笑，但心中已经开始思考下一步的行动。他知道，这只是开始。鞑靼的主力还在后面，真正的考验即将到来。"""),
}

# Write chapters that need rewriting
for fname in needs_rewrite:
    # Extract chapter number
    num_str = fname[:3]
    if num_str in plots:
        cn_num, title, plot = plots[num_str]
        header = f"# 第{cn_num}章 {title}\n\n"
        
        # Split plot into paragraphs
        sentences = plot.split("。")
        paragraphs = []
        current = ""
        for s in sentences:
            if not s.strip():
                continue
            current += s + "。"
            if len(current) > 300:
                paragraphs.append(current.strip())
                current = ""
        if current.strip():
            paragraphs.append(current.strip())
        
        body = "\n\n".join(paragraphs)
        cliffhanger = paragraphs[-1] if paragraphs else ""
        content = header + body + f"\n\n---\n\n*{cliffhanger}*"
        
        path = os.path.join(CHAPTERS_DIR, fname)
        with open(path, 'w') as f:
            f.write(content)
        print(f"{fname} rewritten ({len(content)} chars)")
    else:
        print(f"{fname} - no plot data available")

print("\nDone!")
